import { MeshBasicNodeMaterial, MeshPhysicalNodeMaterial } from 'three/webgpu';
import { uv, mix, vec3, positionLocal, float } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, Mesh, PlaneGeometry, Shape, ExtrudeGeometry, Color, DirectionalLight } = THREE;

  const group = new Group();
  group.name = 'brand-mark-wall';

  const colors = (config.intent?.visualSpec?.colors) ?? config.colors ?? {
    background: '#0b0b10',
    surface: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    gradientStops: [
      { at: 0, hex: '#1a1a22' },
      { at: 1, hex: '#121218' }
    ]
  };

  const cleanupFns = [];
  const tweens = [];

  // ---------------------------------------------------------------
  // 1. STAGE BACKDROP (7x6 @ z=-2.5, vertical gradient)
  // ---------------------------------------------------------------
  const stops = colors.gradientStops ?? [{ at: 0, hex: '#1a1a22' }, { at: 1, hex: '#121218' }];
  const topC = new Color(stops[0].hex);
  const botC = new Color(stops[stops.length - 1].hex);
  const backdropMat = new MeshBasicNodeMaterial();
  backdropMat.colorNode = mix(
    vec3(botC.r, botC.g, botC.b),
    vec3(topC.r, topC.g, topC.b),
    uv().y
  );
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  group.add(backdrop);

  // ---------------------------------------------------------------
  // 2. TEXT CONTENT (bridging idiom)
  // ---------------------------------------------------------------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const kickerItem = items.find((i) => i.role === 'kicker');
  const brandItems = items.filter((i) => i.role === 'brand-mark');

  const kickerText = kickerItem?.text ?? 'AS FEATURED IN';
  const brandLabels = brandItems.length
    ? brandItems.map((i) => i.text)
    : ['HODINKEE', 'MONOCLE', 'WALLPAPER', 'ESQUIRE', 'WIRED', 'FINANCIAL TIMES'];

  // ---------------------------------------------------------------
  // 3. GRID LAYOUT
  // ---------------------------------------------------------------
  const TILE_W = 1.0;
  const TILE_H = 0.62;
  const GAP = 0.25;
  const COLS = 3;
  const ROWS = 2;
  const PITCH_X = TILE_W + GAP;
  const PITCH_Y = TILE_H + GAP;
  const gridW = COLS * TILE_W + (COLS - 1) * GAP;
  const gridH = ROWS * TILE_H + (ROWS - 1) * GAP;
  const gridTop = gridH / 2 - TILE_H / 2;

  // kicker sits 0.3 above grid top
  const kickerNode = ctx.fontAtlas.createText(kickerText, {
    fontSize: 9,
    color: colors.paper,
    align: 'center',
    letterSpacingPx: 1.2
  });
  kickerNode.position.set(0, gridTop + TILE_H / 2 + 0.3, 0.05);
  group.add(kickerNode);

  // thin accent divider line - foreground depth plane, small accent usage (<10% of frame)
  const accentGeo = new PlaneGeometry(0.6, 0.012);
  const accentMat = new MeshBasicNodeMaterial({ color: new Color(colors.accent) });
  const accentLine = new Mesh(accentGeo, accentMat);
  accentLine.position.set(0, gridTop + TILE_H / 2 + 0.13, 0.06);
  group.add(accentLine);

  // ---------------------------------------------------------------
  // 4. CHAMFERED TILE GEOMETRY (shared)
  // ---------------------------------------------------------------
  function makeChamferedPlate(w, h, thickness = 0.05, bevel = 0.02) {
    const hw = w / 2 - bevel;
    const hh = h / 2 - bevel;
    const shape = new Shape();
    shape.moveTo(-hw, -hh);
    shape.lineTo(hw, -hh);
    shape.lineTo(hw, hh);
    shape.lineTo(-hw, hh);
    shape.lineTo(-hw, -hh);
    const geo = new ExtrudeGeometry(shape, {
      depth: thickness - bevel * 2,
      bevelEnabled: true,
      bevelThickness: bevel,
      bevelSize: bevel,
      bevelSegments: 2,
      steps: 1
    });
    geo.translate(0, 0, -(thickness / 2));
    geo.computeVertexNormals();
    return geo;
  }

  const tileGeo = makeChamferedPlate(TILE_W, TILE_H, 0.05, 0.02);

  // ---------------------------------------------------------------
  // 5. LIGHTS (node-local rim/key rake — scene already gives ambient 0.6 + key 1.2)
  // ---------------------------------------------------------------
  const rakeLight = new DirectionalLight(0xffffff, 0.9);
  const elev = THREE.MathUtils.degToRad(35);
  rakeLight.position.set(Math.cos(elev) * 3, Math.sin(elev) * 3, 3);
  group.add(rakeLight);
  group.add(rakeLight.target);

  const rimLight = new DirectionalLight(0xffffff, 0.6);
  rimLight.position.set(-2, -1, -2);
  group.add(rimLight);
  group.add(rimLight.target);

  // ---------------------------------------------------------------
  // 6. BUILD TILES
  // ---------------------------------------------------------------
  const albedoTop = new Color('#1a1a22');
  const albedoBot = new Color('#121218');

  const tiles = [];
  const disposables = [];

  let idx = 0;
  for (let row = 0; row < ROWS; row++) {
    for (let col = 0; col < COLS; col++) {
      const label = brandLabels[idx] ?? '';
      const tileGroup = new Group();
      const x = (col - 1) * PITCH_X;
      const y = gridTop - row * PITCH_Y;
      tileGroup.position.set(x, y, 0);

      const mat = new MeshPhysicalNodeMaterial();
      const t = positionLocal.y.add(float(TILE_H / 2)).div(float(TILE_H)).clamp(0.0, 1.0);
      mat.colorNode = mix(
        vec3(albedoTop.r, albedoTop.g, albedoTop.b),
        vec3(albedoBot.r, albedoBot.g, albedoBot.b),
        t
      );
      mat.roughness = 0.55;
      mat.metalness = 0.5;
      mat.clearcoat = 0.2;
      mat.clearcoatRoughness = 0.35;
      mat.anisotropy = 0.6;
      mat.anisotropyRotation = 0.0;

      const mesh = new Mesh(tileGeo, mat);
      mesh.position.set(0, 0, 0);
      tileGroup.add(mesh);

      const wordmark = ctx.fontAtlas.createText(label, {
        fontSize: 13,
        color: colors.paper,
        align: 'center',
        letterSpacingPx: 1.0
      });
      wordmark.position.set(0, 0, 0.035);
      tileGroup.add(wordmark);

      // apply 0.78 opacity to wordmark materials
      const wmMats = [];
      wordmark.traverse((o) => {
        if (o.material) {
          o.material.transparent = true;
          o.material.opacity = 0.78;
          wmMats.push(o.material);
        }
      });

      group.add(tileGroup);
      disposables.push(tileGeo, mat, ...wmMats);

      tiles.push({
        group: tileGroup,
        mesh,
        mat,
        wordmark,
        wmMats,
        baseZ: 0,
        row,
        col
      });
      idx++;
    }
  }

  // ---------------------------------------------------------------
  // 7. MOUNT ANIMATION — stagger-cards / fade-up, top row L-to-R first
  // ---------------------------------------------------------------
  const orderedTiles = [...tiles].sort((a, b) => (a.row - b.row) || (a.col - b.col));
  const mountTl = gsap.timeline();
  orderedTiles.forEach((tile, i) => {
    tile.group.position.y += 0.2;
    tile.group.traverse((o) => {
      if (o.material) o.material.opacity = 0.0;
    });
    tile.mat.opacity = 0.0;
    tile.mat.transparent = true;

    mountTl.to(
      tile.group.position,
      { y: tile.group.position.y - 0.2, duration: 0.5, ease: 'power2.out' },
      i * 0.08
    );
    mountTl.to(
      tile.mat,
      { opacity: 1.0, duration: 0.5, ease: 'power2.out' },
      i * 0.08
    );
    tile.wmMats.forEach((m) => {
      m.opacity = 0.0;
      mountTl.to(m, { opacity: 0.78, duration: 0.5, ease: 'power2.out' }, i * 0.08);
    });
  });
  tweens.push(mountTl);

  // ---------------------------------------------------------------
  // 8. HOVER INTERACTION HANDLERS
  // ---------------------------------------------------------------
  function findTileFromObject(obj) {
    let cur = obj;
    while (cur) {
      const hit = tiles.find((t) => t.group === cur);
      if (hit) return hit;
      cur = cur.parent;
    }
    return null;
  }

  function setHover(tile, isHover) {
    const zTarget = isHover ? 0.05 : 0.0;
    const opTarget = isHover ? 1.0 : 0.78;
    const tl = gsap.timeline();
    tl.to(tile.mesh.position, { z: zTarget, duration: 0.16, ease: 'power2.out' }, 0);
    tile.wmMats.forEach((m) => {
      tl.to(m, { opacity: opTarget, duration: 0.16, ease: 'power2.out' }, 0);
    });
    tweens.push(tl);
  }

  group.userData.handlers = {
    pointerover: (event) => {
      const obj = event?.object ?? event?.target;
      const tile = obj ? findTileFromObject(obj) : null;
      if (tile) setHover(tile, true);
    },
    pointerout: (event) => {
      const obj = event?.object ?? event?.target;
      const tile = obj ? findTileFromObject(obj) : null;
      if (tile) setHover(tile, false);
      else tiles.forEach((t) => setHover(t, false));
    },
    pointermove: (event) => {
      const obj = event?.object ?? event?.target;
      const tile = obj ? findTileFromObject(obj) : null;
      if (!tile) return;
      tiles.forEach((t) => {
        if (t !== tile && t.mesh.position.z !== 0) setHover(t, false);
      });
      setHover(tile, true);
    }
  };

  // ---------------------------------------------------------------
  // 9. CINEMATIC PRIMITIVES (apply any declared, generically)
  // ---------------------------------------------------------------
  const primitiveHandles = [];
  const primitiveList = config.cinematicPrimitives ?? [];
  for (const prim of primitiveList) {
    const fn = ctx.primitives?.[prim.name];
    if (typeof fn === 'function') {
      const handle = fn(group, prim.params ?? {});
      if (handle) primitiveHandles.push(handle);
    }
  }

  // ---------------------------------------------------------------
  // 10. CLEANUP
  // ---------------------------------------------------------------
  group.userData.cleanup = () => {
    mountTl.kill();
    tweens.forEach((tl) => tl.kill?.());
    primitiveHandles.forEach((h) => h.cleanup?.());

    backdropGeo.dispose();
    backdropMat.dispose();
    accentGeo.dispose();
    accentMat.dispose();
    tileGeo.dispose();

    tiles.forEach((tile) => {
      tile.mat.dispose();
      tile.wmMats.forEach((m) => m.dispose?.());
    });

    group.traverse((o) => {
      if (o.geometry && o.geometry !== tileGeo && o.geometry !== backdropGeo && o.geometry !== accentGeo) {
        o.geometry.dispose?.();
      }
    });
  };

  return group;
}
